        if (entity_uuid != null) {
            recruit.depositEntityUUID = entity_uuid;
            recruit.depositPos = null;
        }
        else if (blockPos != null) {
            recruit.depositPos = blockPos;
            recruit.depositEntityUUID = null;
        }
    }

public static void onUpkeepCommand(UUID player_uuid, AbstractRecruitEntity recruit, UUID group, boolean isEntity, UUID entity_uuid, BlockPos blockPos) {
        if (recruit.isEffectedByCommand(player_uuid, group)){
            if (isEntity) {
                //Main.LOGGER.debug("server: entity_uuid: " + entity_uuid);
                recruit.setUpkeepUUID(Optional.of(entity_uuid));
                recruit.clearUpkeepPos();
            }
            else {
                recruit.setUpkeepPos(blockPos);
                recruit.clearUpkeepEntity();
            }
            recruit.forcedUpkeep = true;
            recruit.setUpkeepTimer(0);
            onClearTargetButton(player_uuid, recruit, group);
        }
    }

public static void onHarbourCommand(ServerPlayer player, CaptainEntity captain) {
        Entity ship = captain.getVehicle();
        if (!captain.isSteeringShip() || ship == null) {
            player.sendSystemMessage(Component.translatable("chat.recruits.text.captain_harbour_no_ship", captain.getName().getString()));
