public static boolean isVersionAtLeast(String installedVersion, String minVersion) {
        String[] installed = installedVersion.split("[.\\-]", -1);
        String[] minimum  = minVersion.split("[.\\-]", -1);

        int len = Math.max(installed.length, minimum.length);
        for (int i = 0; i < len; i++) {
            String a = i < installed.length ? installed[i] : "0";
            String b = i < minimum.length  ? minimum[i]   : "0";

            int cmp;
            try {
                cmp = Integer.compare(Integer.parseInt(a), Integer.parseInt(b));
            } catch (NumberFormatException e) {
                cmp = a.compareTo(b);
            }

            if (cmp != 0) return cmp > 0;
        }
        return true;
    }

public static int getPromotionLevel(int profession) {
        return switch (profession) {
            case 0, 1 -> 2; // messenger, scout
            case 2 -> 3;    // siege engineer
            case 3, 4 -> 5; // captain, patrol leader
            case 6 -> 7;    // governor
            default -> -1;
        };
    }

public static int getPromotionLevel(EntityType<?> type) {
        for (Map.Entry<Integer, EntityType<? extends AbstractRecruitEntity>> entry : entitiesByProfession.entrySet()) {
            if (entry.getValue() == type) return getPromotionLevel(entry.getKey());
        }
        return -1;
    }

public static void promoteRecruit(AbstractRecruitEntity recruit, int profession, String name, ServerPlayer player) {
        RecruitEvent.Promoted promoteEvent = new RecruitEvent.Promoted(recruit, profession, name, player);
        MinecraftForge.EVENT_BUS.post(promoteEvent);
        if (promoteEvent.isCanceled()) return;

        EntityType<? extends AbstractRecruitEntity> companionType = entitiesByProfession.get(profession);
        if (companionType == null) return;

        // Governor: any own recruit; the claim is chosen in the Governor screen (or taken right away
        // if he stands in an own claim without Governor)
        if (profession == 6 && !GovernorOffice.canPromote(recruit, player)) return;

        AbstractRecruitEntity abstractRecruit = companionType.create(recruit.getCommandSenderWorld());
        if (abstractRecruit instanceof GovernorEntity governor) {
            governor.setCustomName(Component.literal(name));
            governor.copyPosition(recruit);
            governor.applyRecruitValues(recruit);
            governor.setOwnerName(player.getName().getString());
            GovernorOffice.setupPromoted(governor, recruit, player);
            return;
        }
        if (abstractRecruit instanceof ICompanion companion) {
            abstractRecruit.setCustomName(Component.literal(name));
            abstractRecruit.copyPosition(recruit);
            companion.applyRecruitValues(recruit);
            companion.setOwnerName(player.getName().getString());

            UUID groupUUID = recruit.getGroup();

            recruit.discard();
            abstractRecruit.getCommandSenderWorld().addFreshEntity(abstractRecruit);

            if (groupUUID != null && !recruit.getCommandSenderWorld().isClientSide()) {
                ServerLevel serverLevel = (ServerLevel) abstractRecruit.getCommandSenderWorld();
                recruitsGroupsManager.addMember(groupUUID, abstractRecruit.getUUID(), serverLevel);
                recruitsGroupsManager.removeMember(groupUUID, recruit.getUUID(), serverLevel);

                recruitsGroupsManager.broadCastGroupsToPlayer(player);
            }

        }
    }

