        LivingEntity hurtingMob = this.recruit.getLastHurtByMob();
        this.recruit.setTarget(hurtingMob);
        this.targetMob = this.recruit.getTarget();
        this.timestamp = this.recruit.getLastHurtByMobTimestamp();
        this.unseenMemoryTicks = 300;
        if (this.alertSameType) {
            this.alertOthers();
        }

        super.start();
    }

protected void alertOthers() {
        double d0 = this.getFollowDistance();
        AABB axisalignedbb = AABB.unitCubeFromLowerCorner(this.recruit.position())
                .inflate(d0, 16.0D, d0);
        List<? extends AbstractRecruitEntity> list = this.recruit.getCommandSenderWorld()
                .getEntitiesOfClass(this.recruit.getClass(), axisalignedbb);

        for (AbstractRecruitEntity recruitToAlert : list) {
            if (this.recruit == recruitToAlert ||
                    recruitToAlert.getTarget() != null ||
                    this.recruit.getLastHurtByMob() == null ||
                    this.recruit.getLastHurtByMob() == null ||
                    recruitToAlert.getOwnerUUID() == null ||
                    !recruitToAlert.getOwnerUUID().equals(this.recruit.getOwnerUUID()) ||
                    recruitToAlert.isAlliedTo(this.recruit.getLastHurtByMob())) continue;

            boolean shouldIgnore = false;
            if (this.toIgnoreAlert != null) {
                for (Class<?> oclass : this.toIgnoreAlert) {
                    if (recruitToAlert.getClass() == oclass) {
                        shouldIgnore = true;
                        break;
                    }
                }
            }
            if (shouldIgnore) continue;

            this.alertOther(recruitToAlert, this.recruit.getLastHurtByMob());
        }
    }

public RecruitMeleeAttackGoal(AbstractRecruitEntity recruit, double speedModifier, double range) {
        this.recruit = recruit;
        this.speedModifier = speedModifier;

        this.range = range;
        this.setFlags(EnumSet.of(Goal.Flag.MOVE, Goal.Flag.LOOK));
    }

public boolean canUse() {
        LivingEntity target = this.recruit.getTarget();

        if (target == null || !target.isAlive()) {
            return false;
        }

        boolean isClose = target.distanceToSqr(this.recruit) <= range * range;
        boolean canSee = this.recruit.getSensing().hasLineOfSight(target);
        if (isClose && canSee && canAttackHoldPos() && recruit.getState() != 3 && !recruit.needsToGetFood() && !recruit.getShouldMount() && !recruit.getShouldMovePos()) {
            double distance = this.recruit.distanceToSqr(target.getX(), target.getY(), target.getZ());
            this.path = this.recruit.getNavigation().createPath(target, 0);
            if (this.path != null) {
                return true;
            } else {
                double reach = AttackUtil.getAttackReachSqr(recruit);
                return (reach >= distance) && canAttackHoldPos();
            }
        }

        return false;
    }

public boolean canContinueToUse() {
        LivingEntity target = this.recruit.getTarget();
        if (target == null || !target.isAlive()) {
            return false;
        } else if (!this.recruit.getSensing().hasLineOfSight(target)) {
            // Option 2: drop the target when line of sight is lost so the recruit does not keep
            // it queued while behind cover. The move-towards goal is also LoS-gated, so once sight
            // is gone nothing chases; the next search re-acquires only if the target becomes
            // visible again.
            this.recruit.setTarget(null);
            return false;
        } else {
            boolean canAttackHoldPos = canAttackHoldPos();
            boolean needsToGetFood = recruit.needsToGetFood();
            boolean getShouldMount = recruit.getShouldMount();
            boolean getShouldMovePos = recruit.getShouldMovePos();
            return (!(target instanceof Player) || !target.isSpectator() && !((Player) target).isCreative()) && canAttackHoldPos && recruit.getState() != 3 && !needsToGetFood && !getShouldMount && !getShouldMovePos;
        }
    }

public void start() {
        this.recruit.setAggressive(true);
        this.pathingCooldown = 0;

        this.recruit.switchMainHandItem(itemStack -> itemStack.getItem() instanceof SwordItem || itemStack.getItem() instanceof AxeItem);
    }

public void stop() {
        LivingEntity target = this.recruit.getTarget();
        if (!EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target)) {
            this.recruit.setTarget(null);
        }

        if(recruit.getShouldRanged()){
            if(this.recruit instanceof CrossBowmanEntity) this.recruit.switchMainHandItem(itemStack -> itemStack.getItem() instanceof CrossbowItem);
            if(this.recruit instanceof BowmanEntity) this.recruit.switchMainHandItem(itemStack -> itemStack.getItem() instanceof BowItem);
        }

        this.recruit.setAggressive(false);
        if (!recruit.isFollowing()) this.recruit.getNavigation().stop();
    }

public void tick() {
        if (this.pathingCooldown > 0) this.pathingCooldown--;

        this.recruit.tryJumpOverTerrain();

        LivingEntity target = this.recruit.getTarget();
        if (target != null && target.isAlive()) {
            this.recruit.getLookControl().setLookAt(target, 30.0F, 30.0F);
            double distanceToTarget = this.recruit.distanceToSqr(target.getX(), target.getY(), target.getZ());
            double reach = AttackUtil.getAttackReachSqr(recruit);

            boolean canSee = this.recruit.getSensing().hasLineOfSight(target);
            boolean isNotFollowing = !recruit.isFollowing();
            boolean coolDownElapsed = this.pathingCooldown <= 0;

            if (distanceToTarget <= reach && canSee) {
                if (isNotFollowing) this.recruit.getNavigation().stop();
                AttackUtil.performAttack(this.recruit, target);
            }
            else if (canSee && isNotFollowing && coolDownElapsed && !recruit.holdFormation) {
                this.pathingCooldown = 4 + this.recruit.getRandom().nextInt(4);

                if (distanceToTarget > 2024.0D) {
                    this.pathingCooldown += 10;
                } else if (distanceToTarget > 256.0D) {
                    this.pathingCooldown += 5;
                }
                this.recruit.getNavigation().moveTo(target, this.speedModifier);
            }
        }
    }

private boolean canAttackHoldPos() {
        Vec3 pos = recruit.getHoldPos();
        LivingEntity target = this.recruit.getTarget();
        if (target != null && pos != null && recruit.getShouldHoldPos()) {
            double distanceToPos = target.distanceToSqr(pos);
            double ref = 400;

            return distanceToPos < ref;
        }
        return true;
    }

public RecruitMoveTowardsTargetGoal(AbstractRecruitEntity recruit, double speedModifier, float within) {
        this.recruit = recruit;
        this.speedModifier = speedModifier;
        this.within = within;
    }

public boolean canUse() {
        this.target = this.recruit.getTarget();
        if (this.recruit.getState() == 3 || recruit.getShouldMount() || recruit.needsToGetFood() || this.recruit.isFollowing() || this.recruit.getShouldMovePos()){
            return false;
        }
        else if (this.target == null) {
            return false;
        }
        else if(this.recruit.holdFormation){
            return false;
        }
        else if(this.recruit.isInFormation && this.target.distanceToSqr(this.recruit) > AttackUtil.getAttackReachSqr(recruit) * 1.5){
            return false;
        }
        else if (this.target.distanceToSqr(this.recruit) > (double)(this.within * this.within)) {
            return false;
        }
        else if (!this.recruit.getSensing().hasLineOfSight(this.target)) {
            // Option 2: only approach a target the recruit can actually see. Without line of sight
            // the recruit does not chase enemies behind walls. The expensive LoS raycast is cached
            // per tick by EntitySensing, and the attack goals query it too, so this adds no extra
            // raycast in practice.
            return false;
        }
        else {
            Vec3 vec3 = DefaultRandomPos.getPosTowards(this.recruit, 16, 7, this.target.position(), (double)((float)Math.PI / 2F));
            if (vec3 == null) {
                return false;
            } else {
                this.wantedX = vec3.x;
                this.wantedY = vec3.y;
                this.wantedZ = vec3.z;
                return true;
            }
        }
    }

public boolean canContinueToUse() {
        if (this.recruit.isFollowing()){
            return false;
        }
        return !this.recruit.getNavigation().isDone() && this.target.isAlive() && this.target.distanceToSqr(this.recruit) < (double)(this.within * this.within) && this.recruit.getSensing().hasLineOfSight(this.target);
    }

