public void start() {
        if (!this.recruit.isFollowing()) {
            this.recruit.getNavigation().moveTo(this.wantedX, this.wantedY, this.wantedZ, this.speedModifier);
        }
    }

public void tick(){
        if (this.target == null){
            stop();
        }
        this.recruit.tryJumpOverTerrain();
    }

