public RecruitRangedBowAttackGoal(T mob, double speedModifier, int attackIntervalMin, int attackIntervalMax, float attackRadius, double stopRange) {
        this.recruit = mob;
        this.speedModifier = speedModifier;
        this.attackIntervalMin = attackIntervalMin;
        this.attackIntervalMax = attackIntervalMax;
        this.attackRadius = attackRadius;
        this.stopRange = stopRange;
        this.setFlags(EnumSet.of(Goal.Flag.LOOK));
        this.consumeArrows = RecruitsServerConfig.RangedRecruitsNeedArrowsToShoot.get();
    }

public boolean canUse() {
        LivingEntity livingentity = this.recruit.getTarget();
        if (livingentity != null && livingentity.isAlive()) {
            if(this.recruit.getShouldRanged() && IRangedRecruit.isTooDeepUnderwater(livingentity)){
                this.recruit.setTarget(null);
                return false;
            }
            if(!isHoldingBow(this.recruit)){
                recruit.switchMainHandItem(RecruitRangedBowAttackGoal::isBow);

                return false;
            }

            this.target = livingentity;
            float distance = this.target.distanceTo(this.recruit);

            boolean canTackMovePos = canAttackMovePos();
            boolean shouldRanged = this.recruit.getShouldRanged();
            boolean canAttack = this.recruit.canAttack(target);
            boolean notPassive = this.recruit.getState() != 3;
            boolean notNeedsToGetFood = !this.recruit.needsToGetFood();
            boolean canSee = this.recruit.getSensing().hasLineOfSight(target);
            // Option 2: only engage targets that are actually visible. Without line of sight
            // the target is dropped so the recruit does not chase enemies behind walls.
            // (LoS in the area search is disabled; this goal-level check is the single source
            // of truth for "may I act on this target".)
            if(!canSee){
                recruit.setTarget(null);
                return false;
            }
            return distance >= stopRange && canTackMovePos && notNeedsToGetFood && canAttack && notPassive && shouldRanged;
        } else {
            return false;
        }
    }

public static boolean isHoldingBow(LivingEntity mob) {
        return mob.isHolding(RecruitRangedBowAttackGoal::isBow);
    }

public static boolean isBow(ItemStack stack){
        String name = stack.getDescriptionId();
        return stack.is(Items.BOW) || stack.getItem() instanceof BowItem || stack.getItem() instanceof ProjectileWeaponItem || name.contains("bow");
    }

private boolean hasArrows(){
        return !consumeArrows || this.recruit.getInventory().hasAnyMatching(item -> item.is(ItemTags.ARROWS));
    }

public boolean canContinueToUse() {
        return this.canUse() && isHoldingBow(this.recruit);
    }

public void start() {
        super.start();
        this.recruit.setAggressive(true);
    }

public void stop() {
        super.stop();
        this.recruit.setAggressive(false);
        this.target = null;
        this.seeTime = 0;
        this.attackTime = -1;
        this.recruit.stopUsingItem();
    }

public void tick() {
        if(target != null && target.isAlive()) {
            double distance = target.distanceToSqr(this.recruit);
            boolean isClose = distance <= 150;
            boolean isFar = distance >= 3500;
            boolean isTooFar = distance >= 4500;
            boolean inRange =  !isFar;
            boolean canSee = this.recruit.getSensing().hasLineOfSight(target);

            if (canSee) {
                ++this.seeTime;
            } else {
                this.seeTime = 0;
            }

            if(isTooFar){
                this.recruit.setTarget(null);
                this.stop();
                return;
            }

            // movement
            if (this.recruit.getShouldFollow() && this.recruit.getOwner() != null) {
                handleFollow(this.recruit.getOwner(), inRange, isFar, isClose);
            }
            else if(this.recruit.getShouldHoldPos() && this.recruit.getHoldPos() != null){
                handleHoldPos(this.recruit.getHoldPos(), inRange);
            }
            else {
                handleWander(inRange, isFar, isClose);
            }

            this.recruit.getLookControl().setLookAt(target, 30.0F, 30.0F);
            if (this.recruit.isUsingItem()) {
                if (!canSee && this.seeTime < -60) {
                    this.recruit.stopUsingItem();
                }
                else if (canSee) {
                    int i = this.recruit.getTicksUsingItem();
                    if (i >= 20) {
                        this.recruit.stopUsingItem();
                        this.recruit.performRangedAttack(target, BowItem.getPowerForTime(i));
                        float f = Mth.sqrt((float) distance) / this.attackRadius;
                        this.attackTime = Mth.floor(f * (float) (this.attackIntervalMax - this.attackIntervalMin) + (float) this.attackIntervalMin);
                    }
                }
            }
            else if (--this.attackTime <= 0 && this.seeTime >= -60 && this.hasArrows()) {
                this.recruit.startUsingItem(InteractionHand.MAIN_HAND);
            }
        }
    }

private boolean canAttackMovePos() {
        LivingEntity target = this.recruit.getTarget();
        BlockPos pos = this.recruit.getMovePos();

        if (target != null && pos != null && this.recruit.getShouldMovePos()) {
            boolean targetIsFar = target.distanceToSqr(this.recruit) >= 320;
            boolean posIsClose = pos.distSqr(this.recruit.getOnPos()) <= 150;
            boolean posIsFar = pos.distSqr(this.recruit.getOnPos()) > 150D;

            if (posIsFar) {
                return false;
            }

            else if (posIsClose && targetIsFar){
                return false;
            }
        }
        return true;
    }

private void handleFollow(@NotNull LivingEntity owner, boolean inRange, boolean isFar, boolean isClose){
        boolean ownerClose = owner.distanceToSqr(this.recruit) <= 100;

        if (ownerClose) {
            if (inRange) this.recruit.getNavigation().stop();
            if (isFar) this.recruit.getNavigation().moveTo(target, this.speedModifier);
            if (isClose) this.recruit.fleeEntity(target);
        }
    }

private void handleHoldPos(@NotNull Vec3 pos, boolean inRange){
        boolean posClose = pos.distanceToSqr(this.recruit.position()) <= 50;

        if (posClose) {
            if (inRange) this.recruit.getNavigation().stop();
        }
    }

private void handleWander(boolean inRange, boolean isFar, boolean isClose){
        if (inRange) this.recruit.getNavigation().stop();
        if (isFar) this.recruit.getNavigation().moveTo(target, this.speedModifier);
        if (isClose) this.recruit.fleeEntity(target);
    }

public RecruitRangedCrossbowAttackGoal(CrossBowmanEntity crossBowman, double stopRange) {
        this.weapon = new CrossbowWeapon();
        this.crossBowman = crossBowman;
        this.speedModifier = this.weapon.getMoveSpeedAmp();
        this.stopRange = stopRange;
        this.setFlags(EnumSet.of(Goal.Flag.LOOK));
        this.consumeArrows = RecruitsServerConfig.RangedRecruitsNeedArrowsToShoot.get();
    }

public boolean canUse() {
        this.target = this.crossBowman.getTarget();
        boolean shouldRanged = crossBowman.getShouldRanged();
        if (target != null && target.isAlive() && shouldRanged) {
            if(IRangedRecruit.isTooDeepUnderwater(target)){
                this.crossBowman.setTarget(null);
                return crossBowman.getShouldStrategicFire();
            }
            // Target inside melee range: leave the weapon alone so the melee goal keeps its sword.
            if(target.distanceTo(this.crossBowman) < stopRange) return false;

            if(!this.isWeaponInMainHand()){
                // Do not fight the musket goal over the main hand.
                if(!(Main.isMusketModLoaded && IWeapon.isMusketModWeapon(this.crossBowman.getMainHandItem()))){
                    this.crossBowman.switchMainHandItem(RecruitRangedCrossbowAttackGoal::isCrossbow);
                }
                return false;
            }
            // Option 2: only engage a visible target. Without line of sight the target is dropped
            // so the crossbowman does not chase enemies behind cover. Strategic fire (no concrete
            // target) is handled in the else branch and stays unaffected.
            if(!this.crossBowman.getSensing().hasLineOfSight(target)){
                this.crossBowman.setTarget(null);
                return crossBowman.getShouldStrategicFire();
            }
            return target.distanceTo(this.crossBowman) >= stopRange && this.canAttackMovePos() && !this.crossBowman.needsToGetFood() && !this.crossBowman.getShouldMount();
        } else {
            return crossBowman.getShouldStrategicFire();
        }
    }

public boolean canContinueToUse() {
        return this.canUse();
    }

@Override
    public void start() {
        super.start();
        this.crossBowman.setAggressive(true);
        this.state = State.IDLE;
    }

@Override
    public void stop() {
        super.stop();
        this.seeTime = 0;
        this.crossBowman.stopUsingItem();
        this.crossBowman.setAggressive(false);
    }

protected boolean isWeaponInMainHand() {
        if(isCrossbow(crossBowman.getMainHandItem())) {
            this.weapon = new CrossbowWeapon();
            return true;
        }
        else
            return false;
    }

protected static boolean isCrossbow(ItemStack itemStack){
        return itemStack.is(Items.CROSSBOW) || itemStack.getItem() instanceof CrossbowItem;
    }

public void tick() {
        if(target != null && target.isAlive()) {
            double distance = target.distanceToSqr(this.crossBowman);
            boolean isClose = distance <= 150;
            boolean isFar = distance >= 3500;
            boolean isTooFar = distance >= 4500;
            boolean inRange =  !isFar;
            boolean canSee = this.crossBowman.getSensing().hasLineOfSight(target);

            if (canSee) {
                ++this.seeTime;
            } else {
                this.seeTime = 0;
            }

            if(isTooFar){
                this.crossBowman.setTarget(null);
                this.stop();
                return;
            }

            // movement
            if (crossBowman.getShouldFollow() && crossBowman.getOwner() != null) {
                handleFollow(this.crossBowman.getOwner(), inRange, isFar);
            }
            else if(crossBowman.getShouldHoldPos() && crossBowman.getHoldPos() != null){
                handleHoldPos(crossBowman.getHoldPos(), inRange);
            }
            else {
                handleWander(inRange, isFar, isClose);
            }
        }

        //WEAPON HANDLING
        if(isWeaponInMainHand()) {
            if(crossBowman.getShouldStrategicFire() && target == null) {
                BlockPos pos = crossBowman.getStrategicFirePos();
                switch (state) {
                    case IDLE -> {
                        if (weapon.isLoaded(crossBowman.getMainHandItem())) {
                            if (pos != null) {
                                this.state = State.AIMING;
                            }
                        } else if(hasArrows()) this.state = State.RELOAD;
                    }

                    case RELOAD -> {
                        this.crossBowman.startUsingItem(InteractionHand.MAIN_HAND);

                        int i = this.crossBowman.getTicksUsingItem();
                        if (i >= weapon.getWeaponLoadTime()) {
                            this.crossBowman.releaseUsingItem();
                            this.crossBowman.playSound(this.weapon.getLoadSound(), 1.0F, 1.0F / (crossBowman.getRandom().nextFloat() * 0.4F + 0.8F));
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), true);

                            this.state = State.AIMING;
                        }
                    }

                    case AIMING -> {
                        if (pos != null) {
                            this.crossBowman.setAggressive(true);
                            this.crossBowman.getLookControl().setLookAt(pos.getX(), pos.getY(), pos.getZ());

                            if (++this.seeTime > weapon.getWeaponLoadTime()) {
                                this.state = State.SHOOT;
                                this.seeTime = 0;
                            }
                        }
                    }

                    case SHOOT -> {
                        if (pos != null) {
                            this.weapon.performRangedAttackIWeapon(this.crossBowman, pos.getX(), pos.getY(), pos.getZ(), weapon.getProjectileSpeed());
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), false);
                        }
                        this.state = State.IDLE; //RESUPPLY
                    }
                }
            }
            else {
                switch (state) {
                    case IDLE -> {
                        if (weapon.isLoaded(crossBowman.getMainHandItem())) {
                            if (target != null && target.isAlive()) {
                                this.state = State.AIMING;
                            }
                        } else if(hasArrows()) this.state = State.RELOAD;
                    }
                    case RELOAD -> {
                        this.crossBowman.startUsingItem(InteractionHand.MAIN_HAND);

                        int i = this.crossBowman.getTicksUsingItem();
                        if (i >= weapon.getWeaponLoadTime()) {
                            this.crossBowman.releaseUsingItem();
                            this.crossBowman.playSound(this.weapon.getLoadSound(), 1.0F, 1.0F / (crossBowman.getRandom().nextFloat() * 0.4F + 0.8F));
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), true);

                            this.state = State.AIMING;
                        }
                    }

                    case AIMING -> {
                        if (target != null && target.isAlive()) {
                            boolean canSee = this.crossBowman.getSensing().hasLineOfSight(target);
                            this.crossBowman.setAggressive(true);
                            this.crossBowman.getLookControl().setLookAt(target);

                            if (canSee) {
                                if (++this.seeTime >= weapon.getWeaponLoadTime()) {
                                    this.state = State.SHOOT;
                                    this.seeTime = 0;
                                }
                            } else if (crossBowman.getShouldHoldPos()) {
                                this.crossBowman.setTarget(null);
                            }
                        } else {
                            this.crossBowman.setAggressive(false);
                            seeTime = 0;
                        }
                    }

                    case SHOOT -> {
                        LivingEntity savedTarget = null;
                        if (target != null && target.isAlive() && this.crossBowman.canAttack(target) && this.crossBowman.getState() != 3) {
                            this.crossBowman.getLookControl().setLookAt(target);

                            if(AttackUtil.canPerformHorseAttack(this.crossBowman, target)){
                                if(target.getVehicle() instanceof LivingEntity) {
                                    savedTarget = target;
                                    target = (LivingEntity) target.getVehicle();
                                }
                            }

                            this.weapon.performRangedAttackIWeapon(this.crossBowman, target.getX(), target.getY() + target.getEyeHeight(), target.getZ(), weapon.getProjectileSpeed());

                            if(savedTarget != null){
                                target = savedTarget;
                            }

                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), false);
                        }
                        this.state = State.IDLE;
                    }
                }
            }
        }
    }

private boolean hasArrows(){
        return !consumeArrows || this.crossBowman.getInventory().hasAnyMatching(item -> item.is(ItemTags.ARROWS));
    }

private boolean canAttackMovePos() {
        LivingEntity target = this.crossBowman.getTarget();
        BlockPos pos = crossBowman.getMovePos();

        if (target != null && pos != null && crossBowman.getShouldMovePos()) {
            boolean targetIsFar = target.distanceTo(this.crossBowman) >= 32D;
            boolean posIsClose = pos.distSqr(this.crossBowman.getOnPos()) <= 15.0D;
            boolean posIsFar = pos.distSqr(this.crossBowman.getOnPos()) > 15.0D;

            if (posIsFar) {
                return false;
            }

            else if (posIsClose && targetIsFar){
                return false;
            }
        }
        return true;
    }

private void handleFollow(@NotNull LivingEntity owner, boolean inRange, boolean isFar){
        boolean ownerClose = owner.distanceToSqr(this.crossBowman) <= 100;

        if (ownerClose) {
            if (inRange) this.crossBowman.getNavigation().stop();
            if (isFar) this.crossBowman.getNavigation().moveTo(target, this.speedModifier);
        }
    }

private void handleHoldPos(@NotNull Vec3 pos, boolean inRange){
        boolean posClose = pos.distanceToSqr(this.crossBowman.position()) <= 50;

        if (posClose) {
            if (inRange) this.crossBowman.getNavigation().stop();
        }
    }

private void handleWander(boolean inRange, boolean isFar, boolean isClose){
        if (inRange) this.crossBowman.getNavigation().stop();
        if (isFar) this.crossBowman.getNavigation().moveTo(crossBowman, this.speedModifier);
    }

public PatrolLeaderAttackController(AbstractLeaderEntity recruit) {
        this.leader = recruit;
    }

public void start(){
        if(!this.leader.getCommandSenderWorld().isClientSide() && leader.enemyArmy != null && leader.army != null){
            double distanceToTarget = this.leader.army.getPosition().distanceToSqr(leader.enemyArmy.getPosition());

            this.leader.army.updateArmy();
            this.leader.enemyArmy.updateArmy();

            if(leader.enemyArmy.size() == 0){
                // enemy army defeated
                this.leader.enemyArmy = null;
                return;
            }
            //To far from init pos -> enemy army is retreating
            if(initPos != null && initPos.distanceToSqr(this.leader.army.getPosition()) > 5000){
                this.leader.enemyArmy = null;
                return;
            }

            RecruitCommanderUtil.setRecruitsAggroState(this.leader.army.getAllRecruitUnits(), leader.getState());


            RecruitCommanderUtil.setRecruitsMoveSpeed(this.leader.army.getAllRecruitUnits(), 1.0F);
            this.setRecruitsTargets();

            if(distanceToTarget < 2500) {
                if(isArmyScattered()){
                    regroupArmy();
                    return;
                }
                leader.commandCooldown = 400;


                if(leader.getEnemyAction() == AbstractLeaderEntity.EnemyAction.HOLD.getIndex()){
                    this.leader.getNavigation().stop();
                    this.setRecruitsTargets();
                    return;
                }

                commandArmy(this.leader.army, this.leader.enemyArmy);
            }
            else{
                if(leader.getOwner() != null) this.leader.getOwner().sendSystemMessage(Component.literal(leader.getName().getString() + ": Enemy contact! Im advancing, their size is " + leader.enemyArmy.size()));
                forwarding();
                leader.commandCooldown = 250;
            }
        }
    }

public void tick() {
        if(leader.commandCooldown == 0){
            leader.commandCooldown = 400;
            start();
        }
    }

