    }

public void save(ServerLevel level) {
        RecruitPlayerUnitSaveData data = RecruitPlayerUnitSaveData.get(level);

        for (Map.Entry<UUID, Integer> entry : recruitCountMap.entrySet()) {
            data.setRecruitCount(entry.getKey(), entry.getValue());
        }

        data.setDirty();
    }

public int getRecruitCount(UUID playerUUID) {
        return recruitCountMap.getOrDefault(playerUUID, 0);
    }

public void setRecruitCount(Player player, int count) {
        recruitCountMap.put(player.getUUID(), count);


    }

public void addRecruits(UUID playerUUID, int count) {
        recruitCountMap.put(playerUUID, getRecruitCount(playerUUID) + count);

    }

public void removeRecruits(UUID playerUUID, int count) {
        recruitCountMap.put(playerUUID, Math.max(getRecruitCount(playerUUID) - count, 0));

    }

public void recountRecruits(MinecraftServer server, UUID playerUUID) {
        if (server == null || playerUUID == null) return;

        int owned = 0;
        for (ServerLevel level : server.getAllLevels()) {
            for (AbstractRecruitEntity recruit : level.getEntities(EntityTypeTest.forClass(AbstractRecruitEntity.class), r -> true)) {
                // garrison recruits of a Governor do not count towards the player limit
                if (recruit.isAlive() && recruit.isOwned() && !recruit.isGarrison() && playerUUID.equals(recruit.getOwnerUUID())) {
                    owned++;
                }
            }
        }

        recruitCountMap.put(playerUUID, owned);
    }

public boolean canPlayerRecruit(String stringId, UUID playerUUID) {
        RecruitsFaction recruitsFaction = FactionEvents.recruitsFactionManager.getFactionByStringID(stringId);

        int currentRecruitCount = getRecruitCount(playerUUID);
        int maxRecruitCount = 0;

        if (recruitsFaction == null) {
            maxRecruitCount = RecruitsServerConfig.MaxRecruitsForPlayer.get();
        } else {
            int maxRecruitsInFaction = recruitsFaction.maxNPCs;
            if(maxRecruitsInFaction == 0) maxRecruitsInFaction = 1000000000;

            if (playerUUID.equals(recruitsFaction.getTeamLeaderUUID())) {
                maxRecruitCount = maxRecruitsInFaction;
            } else {
                maxRecruitCount = recruitsFaction.getMaxNPCsPerPlayer();
            }

            if (recruitsFaction.npcs >= maxRecruitsInFaction) {
                return false;
            }
        }

        return currentRecruitCount < maxRecruitCount;
    }

public int getRemainingRecruitSlots(String stringId, UUID playerUUID) {
        RecruitsFaction recruitsFaction = FactionEvents.recruitsFactionManager.getFactionByStringID(stringId);

        int currentRecruitCount = getRecruitCount(playerUUID);
        int maxRecruitCount;

        if (recruitsFaction == null) {
            maxRecruitCount = RecruitsServerConfig.MaxRecruitsForPlayer.get();
        } else {
            if (playerUUID.equals(recruitsFaction.getTeamLeaderUUID())) {
                maxRecruitCount = recruitsFaction.maxNPCs;
            } else {
                maxRecruitCount = recruitsFaction.getMaxNPCsPerPlayer();
            }

            if (recruitsFaction.npcs >= recruitsFaction.maxNPCs) {
                return 0;
            }
        }

        int remaining = maxRecruitCount - currentRecruitCount;
        return Math.max(remaining, 0);
    }

public void broadCastUnitInfoToPlayer(Player player) {
        if (player == null) return;

        String factionID = null;
        if(player.getTeam() != null){
            factionID = player.getTeam().getName();
        }

        Main.SIMPLE_CHANNEL.send(PacketDistributor.PLAYER.with(()-> (ServerPlayer) player),
                new MessageToClientUpdateUnitInfo(
                        RecruitsServerConfig.NobleVillagerNeedsVillagers.get(),
                        getRemainingRecruitSlots(factionID, player.getUUID())
                ));
    }

public static RecruitsTeamSaveData get(ServerLevel level) {
        DimensionDataStorage storage = level.getDataStorage();
        return storage.computeIfAbsent(RecruitsTeamSaveData::load, RecruitsTeamSaveData::new, FILE_ID);
    }

public static RecruitsTeamSaveData load(CompoundTag nbt) {
        RecruitsTeamSaveData data = new RecruitsTeamSaveData();
        if (nbt.contains("Teams", 9)) {
            data.teams = loadTeams(nbt.getList("Teams", 10));
        }
        return data;
    }

private static Map<String, RecruitsFaction> loadTeams(ListTag list) {
        Map<String, RecruitsFaction> loadedTeams = new HashMap<>();
        for (int i = 0; i < list.size(); ++i) {
            CompoundTag nbt = list.getCompound(i);
            RecruitsFaction recruitsFaction = new RecruitsFaction();

            recruitsFaction.setStringID(nbt.getString("TeamName"));
            recruitsFaction.setTeamDisplayName(nbt.getString("TeamDisplayName"));
            recruitsFaction.setTeamLeaderID(nbt.getUUID("TeamLeaderID"));
            recruitsFaction.setTeamLeaderName(nbt.getString("TeamLeaderName"));
            recruitsFaction.setBanner((CompoundTag) nbt.get("TeamBanner"));
            recruitsFaction.setPlayers(nbt.getInt("Players"));
            recruitsFaction.setNPCs(nbt.getInt("NPCs"));

            recruitsFaction.setMaxPlayers(nbt.getInt("MaxPlayers"));
            recruitsFaction.setMaxNPCs(nbt.getInt("MaxNPCs"));

            ListTag joinRequestsList = nbt.getList("JoinRequests", 8);
            for (int j = 0; j < joinRequestsList.size(); ++j) {
                recruitsFaction.getJoinRequests().add(joinRequestsList.getString(j));
            }

            recruitsFaction.setUnitColor(nbt.getByte("Color"));
            recruitsFaction.setTeamColor(nbt.getInt("TeamColor"));
            recruitsFaction.setMaxNPCsPerPlayer(nbt.getInt("maxNpcsPerPlayer"));

            loadedTeams.put(recruitsFaction.getStringID(), recruitsFaction);
        }
        return loadedTeams;
    }

@Override
    public CompoundTag save(CompoundTag nbt) {
        nbt.put("Teams", saveTeams());
        return nbt;
    }

private ListTag saveTeams() {
        ListTag listTag = new ListTag();
        for (RecruitsFaction team : teams.values()) {
            CompoundTag nbt = new CompoundTag();
            nbt.putString("TeamName", team.getStringID());
            nbt.putString("TeamDisplayName", team.getTeamDisplayName());
            nbt.putUUID("TeamLeaderID", team.getTeamLeaderUUID());
            nbt.putString("TeamLeaderName", team.getTeamLeaderName());
            nbt.put("TeamBanner", team.getBanner());
            nbt.putInt("Players", team.getPlayers());
            nbt.putInt("NPCs", team.getNPCs());

            nbt.putInt("MaxPlayers", team.getMaxPlayers());
            nbt.putInt("MaxNPCs", team.getMaxNPCs());

            ListTag joinRequestsTag = new ListTag();
            for (String request : team.getJoinRequests()) {
                joinRequestsTag.add(StringTag.valueOf(request));
            }
            nbt.put("JoinRequests", joinRequestsTag);
            nbt.putByte("Color", team.getUnitColor());
            nbt.putInt("TeamColor", team.getTeamColor());
            nbt.putInt("maxNpcsPerPlayer", team.getMaxNPCsPerPlayer());

            listTag.add(nbt);
        }
        return listTag;
    }

public Map<String, RecruitsFaction> getTeams() {
        return teams;
    }

public void setTeams(Map<String, RecruitsFaction> teams) {
        this.teams = teams;
    }

public void load(ServerLevel level) {
        RecruitsTreatySaveData data = RecruitsTreatySaveData.get(level);
        treaties.clear();
        treaties.putAll(data.getTreaties());
    }

public void save(ServerLevel level) {
        RecruitsTreatySaveData data = RecruitsTreatySaveData.get(level);
        data.setTreaties(treaties);
        data.setDirty();
        broadcastTreatiesToAll(level);
    }

private String makeKey(String factionA, String factionB) {
        String[] sorted = new String[]{factionA, factionB};
        Arrays.sort(sorted);
        return sorted[0] + "|" + sorted[1];
    }

public boolean hasTreaty(String factionA, String factionB) {
        String key = makeKey(factionA, factionB);
        Long expiry = treaties.get(key);
        if (expiry == null) return false;
        return System.currentTimeMillis() < expiry;
    }

public long getTreatyExpiryMillis(String factionA, String factionB) {
        String key = makeKey(factionA, factionB);
        return treaties.getOrDefault(key, 0L);
    }

public long getTreatyRemainingMillis(String factionA, String factionB) {
        long expiry = getTreatyExpiryMillis(factionA, factionB);
        return Math.max(0L, expiry - System.currentTimeMillis());
    }

public void addTreaty(String factionA, String factionB, int durationHours, ServerLevel level) {
        String key = makeKey(factionA, factionB);
        long expiry = System.currentTimeMillis() + (long) durationHours * 3600 * 1000;
        treaties.put(key, expiry);
        save(level);
        notifyTreatyPlayers(factionA, factionB, true, level);
    }

public void addTreatyRaw(String factionA, String factionB, long expiryMs, ServerLevel level) {
        String key = makeKey(factionA, factionB);
        treaties.put(key, expiryMs);
        save(level);
        notifyTreatyPlayers(factionA, factionB, true, level);
    }

public void removeTreaty(String factionA, String factionB, ServerLevel level) {
        String key = makeKey(factionA, factionB);
        if (treaties.remove(key) != null) {
            save(level);
            notifyTreatyPlayers(factionA, factionB, false, level);
        }
    }

public void tick(ServerLevel level) {
        long now = System.currentTimeMillis();
        List<String> expired = new ArrayList<>();
        for (Map.Entry<String, Long> entry : treaties.entrySet()) {
            if (now >= entry.getValue()) {
                expired.add(entry.getKey());
            }
        }
        for (String key : expired) {
            treaties.remove(key);
            String[] parts = key.split("\\|", 2);
            if (parts.length == 2) {
                notifyTreatyPlayers(parts[0], parts[1], false, level);
            }
        }
        if (!expired.isEmpty()) {
            save(level);
        }
    }

private void notifyTreatyPlayers(String factionAId, String factionBId, boolean established, ServerLevel level) {
        if (FactionEvents.recruitsFactionManager == null) return;
        RecruitsFaction factionA = FactionEvents.recruitsFactionManager.getFactionByStringID(factionAId);
        RecruitsFaction factionB = FactionEvents.recruitsFactionManager.getFactionByStringID(factionBId);
        if (factionA == null || factionB == null) return;

        int toastId = established ? 20 : 21;

        List<ServerPlayer> playersA = FactionEvents.recruitsFactionManager.getPlayersInTeam(factionAId, level);
        for (ServerPlayer player : playersA) {
            Main.SIMPLE_CHANNEL.send(PacketDistributor.PLAYER.with(() -> player),
                    new MessageToClientSetDiplomaticToast(toastId, factionB));
        }

        List<ServerPlayer> playersB = FactionEvents.recruitsFactionManager.getPlayersInTeam(factionBId, level);
        for (ServerPlayer player : playersB) {
            Main.SIMPLE_CHANNEL.send(PacketDistributor.PLAYER.with(() -> player),
                    new MessageToClientSetDiplomaticToast(toastId, factionA));
        }
    }

public Map<String, Long> getTreaties() {
        return Collections.unmodifiableMap(treaties);
    }

public void broadcastTreatiesToAll(ServerLevel level) {
        if (level == null) return;
        for (ServerPlayer player : level.players()) {
            Main.SIMPLE_CHANNEL.send(PacketDistributor.PLAYER.with(() -> player),
                    new MessageToClientUpdateTreaties(treaties));
        }
    }

public void broadcastTreatiesToPlayer(ServerPlayer player) {
        if (player == null) return;
        Main.SIMPLE_CHANNEL.send(PacketDistributor.PLAYER.with(() -> player),
                new MessageToClientUpdateTreaties(treaties));
    }

public static CompoundTag mapToNbt(Map<String, Long> treaties) {
        CompoundTag nbt = new CompoundTag();
        treaties.forEach(nbt::putLong);
        return nbt;
    }

public static Map<String, Long> mapFromNbt(CompoundTag nbt) {
        Map<String, Long> map = new HashMap<>();
        for (String key : nbt.getAllKeys()) {
            map.put(key, nbt.getLong(key));
        }
        return map;
    }
